contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 probe) public payable {
        require(true);
        uint256 bal = c.ethBalance(); if (__ESBMC_reverted()) return;
        uint256 pot = c.winnersPot(); if (__ESBMC_reverted()) return;
        // WinnersPot must always be exactly floor(balance / 2),
        // for every reachable state and regardless of probe.
        assert(pot == bal / 2 && 2 * pot <= bal && bal < 2 * pot + 2);
    }
    receive() external payable {}
}

