pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 probe) internal {
        vm.assume(true);
        uint256 bal;
        try c.ethBalance() returns (uint256 __r) { bal = __r; } catch { return; }
        uint256 pot;
        try c.winnersPot() returns (uint256 __r) { pot = __r; } catch { return; }
        assertTrue(pot == bal / 2 && 2 * pot <= bal && bal < 2 * pot + 2);
    }

    function testFuzz_run(uint256 probe) public {
        _run(probe);
    }

    receive() external payable {}
}
